{
  "ok": false,
  "name": "place_label",
  "error": {
    "type": "invalid_params",
    "message": "'anchor' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "alignment": {
          "type": "string",
          "minLength": 1,
          "description": "this document's alignment, or a referenced one as 'BASE:ALIGN-1' (read through the attachment, which must sit at identity)"
        },
        "anchor": {
          "type": [
            "string",
            "number",
            "object"
          ],
          "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '18+00.00' | 1800, optionally '@offset' (ft, right +, e.g. 'PC-1@16', '18+00@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
        },
        "kind": {
          "enum": [
            "station",
            "pc",
            "pt",
            "pi",
            "mc",
            "pcc",
            "prc",
            "bearing",
            "begin",
            "end",
            "equation",
            "curve_data",
            "custom"
          ]
        },
        "content": {
          "type": "string",
          "description": "explicit text; omit to auto-generate from design data the Caltrans way (recorded either way): '24+05.27 BC', 'N 71°33'54\" E 1240.36'', the curve number '1' in a bubble with a leader"
        },
        "side": {
          "enum": [
            "left",
            "right",
            "above",
            "below"
          ],
          "description": "left/right of the stationing direction, or above/below on the paper (resolved to the line's left or right and recorded so); default by kind: station numbers below, bearings above, curve points and equations left, the curve bubble right"
        },
        "label_offset": {
          "type": "number",
          "minimum": 0,
          "description": "distance from the anchor point, feet in model / inches on sheets; default by kind, sized for 1\" = 50' in model: stations 6 ft / 0.12 in, bearings 3 ft / 0.06 in, curve points and equations 22.5 ft / 0.45 in, the curve bubble 40 ft / 0.80 in"
        },
        "rotation": {
          "enum": [
            "along",
            "perpendicular",
            "horizontal"
          ],
          "description": "default by kind: curve points and equations perpendicular (reading bottom to top), the curve number horizontal, the rest along the line"
        },
        "height": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "text height, feet in model / inches on sheets; default 8 ft / 0.10 in"
        },
        "view_rotation": {
          "type": "number",
          "description": "model space: the twist (rotation_deg) of the viewport the labels are read through; they are lettered upright on that sheet instead of in the model (default 0, an untwisted view)"
        },
        "style": {
          "type": "string",
          "minLength": 1
        },
        "halign": {
          "type": "string",
          "enum": [
            "left",
            "center",
            "right"
          ]
        },
        "valign": {
          "type": "string",
          "enum": [
            "bottom",
            "middle",
            "top"
          ]
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "viewport": {
          "type": "string",
          "minLength": 1,
          "description": "sheet space only: viewport id/name carrying the anchor; default = the first viewport whose frame contains the point"
        }
      },
      "required": [
        "space",
        "anchor"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "alignment": "ALIGN-1",
      "anchor": "PC-1"
    }
  },
  "warnings": []
}
